fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    // Pre-allocate a Vec with the same length as the input
    let mut result = Vec::with_capacity(s.len());

    // For each character, convert ASCII 'A'..'Z' to 'a'..'z' by adding 32,
    // otherwise keep it unchanged.
    for &c in s {
        if c >= 'A' && c <= 'Z' {
            // We know c is in ASCII range, so casting to u8 is safe.
            let lower = (c as u8 + 32) as char;
            result.push(lower);
        } else {
            result.push(c);
        }
    }

    result
}

