    #[test]
    fn test_non_ascii() {
        // Non-ASCII letters (e.g. 'Ü') should remain unchanged
        let input: Vec<char> = vec!['A', 'Ü', 'Z', 'ß'];
        let output = to_lowercase(&input);
        let expected: Vec<char> = vec!['a', 'Ü', 'z', 'ß'];
        assert_eq!(output, expected);
    }

